RRB.load({"id": "gd-full-8", "exam": "gd", "label": "Group D full mock 8 (100 Q)", "questions": [{"s": "General Science", "t": "Biology", "q": "The double-helix structure of DNA was proposed in 1953 by:", "o": ["Gregor Mendel and Hugo de Vries", "James Watson and Francis Crick", "Robert Hooke and Robert Brown", "Louis Pasteur and Robert Koch"], "a": 1, "e": "Watson and Crick, using X-ray data from Rosalind Franklin, proposed the double helix in 1953.", "qh": "1953 में DNA की द्वि-कुंडली (डबल हेलिक्स) संरचना किसने बताई?", "oh": ["ग्रेगर मेंडल और ह्यूगो डी व्रीज़", "जेम्स वॉटसन और फ़्रांसिस क्रिक", "रॉबर्ट हुक और रॉबर्ट ब्राउन", "लुई पाश्चर और रॉबर्ट कोच"], "eh": "वॉटसन और क्रिक ने रोज़लिंड फ़्रैंकलिन के X-रे आँकड़ों की मदद से 1953 में द्वि-कुंडली संरचना बताई।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "What is the molar mass of sulphuric acid (H₂SO₄)? (H = 1, S = 32, O = 16)", "o": ["96 g/mol", "82 g/mol", "49 g/mol", "98 g/mol"], "a": 3, "e": "2(1) + 32 + 4(16) = 98 g/mol.", "qh": "सल्फ़्यूरिक अम्ल (H₂SO₄) का मोलर द्रव्यमान क्या है? (H = 1, S = 32, O = 16)", "oh": ["96 g/mol", "82 g/mol", "49 g/mol", "98 g/mol"], "eh": "2(1) + 32 + 4(16) = 98 g/mol।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "Rhizobium bacteria in the root nodules of leguminous plants help in:", "o": ["Absorbing phosphorus", "Fixing atmospheric nitrogen", "Making chlorophyll", "Releasing oxygen"], "a": 1, "e": "Rhizobium converts atmospheric nitrogen into ammonia usable by plants such as peas and beans.", "qh": "दलहनी पौधों की जड़ ग्रंथियों में राइज़ोबियम बैक्टीरिया किसमें मदद करते हैं?", "oh": ["फ़ॉस्फ़ोरस सोखने में", "वायुमंडलीय नाइट्रोजन के स्थिरीकरण में", "क्लोरोफ़िल बनाने में", "ऑक्सीजन छोड़ने में"], "eh": "राइज़ोबियम वायुमंडलीय नाइट्रोजन को अमोनिया में बदलता है जिसे मटर और सेम जैसे पौधे इस्तेमाल करते हैं।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "Kwashiorkor in children is caused mainly by the deficiency of:", "o": ["Vitamin C", "Iodine", "Protein", "Calcium"], "a": 2, "e": "Kwashiorkor results from severe protein deficiency and causes swelling (oedema) and a pot belly.", "qh": "बच्चों में क्वाशियोरकर मुख्य रूप से किसकी कमी से होता है?", "oh": ["विटामिन C", "आयोडीन", "प्रोटीन", "कैल्शियम"], "eh": "क्वाशियोरकर प्रोटीन की गंभीर कमी से होता है और इसमें सूजन और पेट फूलना होता है।", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "Nuclear power reactors produce energy by:", "o": ["Controlled nuclear fission", "Uncontrolled nuclear fusion", "Burning of uranium in oxygen", "Radioactive decay of carbon"], "a": 0, "e": "In a reactor, heavy nuclei such as uranium-235 split in a controlled chain reaction; the Sun gets energy from fusion.", "qh": "परमाणु बिजली रिएक्टर ऊर्जा कैसे पैदा करते हैं?", "oh": ["नियंत्रित नाभिकीय विखंडन से", "अनियंत्रित नाभिकीय संलयन से", "ऑक्सीजन में यूरेनियम जलाकर", "कार्बन के रेडियोधर्मी क्षय से"], "eh": "रिएक्टर में यूरेनियम-235 जैसे भारी नाभिक नियंत्रित शृंखला अभिक्रिया में टूटते हैं; सूर्य को ऊर्जा संलयन से मिलती है।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "The number of particles in one mole of a substance (Avogadro's number) is about:", "o": ["6.022 × 10²³", "3 × 10⁸", "1.6 × 10⁻¹⁹", "9.8 × 10²"], "a": 0, "e": "Avogadro's number is 6.022 × 10²³ per mole. (3 × 10⁸ m/s is the speed of light, 1.6 × 10⁻¹⁹ C the electron charge.)", "qh": "किसी पदार्थ के एक मोल में कणों की संख्या (आवोगाद्रो संख्या) लगभग कितनी है?", "oh": ["6.022 × 10²³", "3 × 10⁸", "1.6 × 10⁻¹⁹", "9.8 × 10²"], "eh": "आवोगाद्रो संख्या 6.022 × 10²³ प्रति मोल है। (3 × 10⁸ m/s प्रकाश की चाल और 1.6 × 10⁻¹⁹ C इलेक्ट्रॉन का आवेश है।)", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "Which is the longest bone in the human body?", "o": ["Tibia", "Humerus", "Radius", "Femur"], "a": 3, "e": "The femur (thigh bone) is the longest and strongest bone.", "qh": "मानव शरीर की सबसे लंबी हड्डी कौन-सी है?", "oh": ["टिबिया", "ह्यूमरस", "रेडियस", "फ़ीमर (जांघ की हड्डी)"], "eh": "फ़ीमर (जांघ की हड्डी) सबसे लंबी और मज़बूत हड्डी है।", "level": "easy"}, {"s": "General Science", "t": "Chemistry", "q": "White phosphorus is stored under water because it:", "o": ["Dissolves in kerosene", "Reacts violently with water", "Turns into red phosphorus in air", "Catches fire on exposure to air"], "a": 3, "e": "White phosphorus ignites in air at about 35 °C; it does not react with water. Sodium, by contrast, is kept in kerosene.", "qh": "सफ़ेद फ़ॉस्फ़ोरस को पानी में क्यों रखा जाता है?", "oh": ["क्योंकि यह केरोसीन में घुल जाता है", "क्योंकि यह पानी से तेज़ी से क्रिया करता है", "क्योंकि यह हवा में लाल फ़ॉस्फ़ोरस बन जाता है", "क्योंकि यह हवा के संपर्क में आते ही जल उठता है"], "eh": "सफ़ेद फ़ॉस्फ़ोरस हवा में लगभग 35 °C पर जल उठता है; यह पानी से क्रिया नहीं करता। सोडियम को इसके उलट केरोसीन में रखा जाता है।", "level": "tough"}, {"s": "General Science", "t": "Physics", "q": "Three resistors of 2 Ω, 3 Ω and 6 Ω are connected in parallel. What is their equivalent resistance?", "o": ["11 Ω", "1 Ω", "2 Ω", "6 Ω"], "a": 1, "e": "1/R = 1/2 + 1/3 + 1/6 = 1 → R = 1 Ω. (Series would give 11 Ω.)", "qh": "2 Ω, 3 Ω और 6 Ω के तीन प्रतिरोध समांतर क्रम में जुड़े हैं। उनका तुल्य प्रतिरोध क्या है?", "oh": ["11 Ω", "1 Ω", "2 Ω", "6 Ω"], "eh": "1/R = 1/2 + 1/3 + 1/6 = 1 → R = 1 Ω। (श्रेणी क्रम में 11 Ω होता।)", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "The movement of water from a dilute solution to a concentrated solution through a semi-permeable membrane is called:", "o": ["Osmosis", "Diffusion", "Transpiration", "Respiration"], "a": 0, "e": "Osmosis is the movement of water molecules across a semi-permeable membrane towards the more concentrated side.", "qh": "अर्ध-पारगम्य झिल्ली से तनु विलयन से सांद्र विलयन की ओर पानी के जाने को क्या कहते हैं?", "oh": ["परासरण", "विसरण", "वाष्पोत्सर्जन", "श्वसन"], "eh": "परासरण में पानी के अणु अर्ध-पारगम्य झिल्ली से ज़्यादा सांद्र तरफ़ जाते हैं।", "level": "easy"}, {"s": "General Science", "t": "Physics", "q": "One horsepower (hp) is equal to about:", "o": ["1000 watts", "550 watts", "746 watts", "100 watts"], "a": 2, "e": "1 hp ≈ 746 W. (550 is foot-pounds per second, not watts.)", "qh": "एक हॉर्सपावर (hp) लगभग कितने के बराबर है?", "oh": ["1000 वाट", "550 वाट", "746 वाट", "100 वाट"], "eh": "1 hp ≈ 746 W। (550 फ़ुट-पाउंड प्रति सेकंड है, वाट नहीं।)", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "In electronics, 'LED' stands for:", "o": ["Light Emitting Diode", "Low Energy Device", "Light Energy Detector", "Linear Electric Diode"], "a": 0, "e": "An LED is a semiconductor diode that gives out light when current flows through it.", "qh": "इलेक्ट्रॉनिक्स में 'LED' का पूरा नाम क्या है?", "oh": ["लाइट एमिटिंग डायोड", "लो एनर्जी डिवाइस", "लाइट एनर्जी डिटेक्टर", "लीनियर इलेक्ट्रिक डायोड"], "eh": "LED एक अर्धचालक डायोड है जो धारा बहने पर प्रकाश देता है।", "level": "easy"}, {"s": "General Science", "t": "Physics", "q": "An electric iron draws a current of 5 A from a 220 V supply. What is its power?", "o": ["44 W", "1100 W", "225 W", "1000 W"], "a": 1, "e": "P = V × I = 220 × 5 = 1100 W.", "qh": "एक बिजली की इस्त्री 220 V सप्लाई से 5 A धारा लेती है। उसकी शक्ति क्या है?", "oh": ["44 W", "1100 W", "225 W", "1000 W"], "eh": "P = V × I = 220 × 5 = 1100 W।", "level": "easy"}, {"s": "General Science", "t": "Chemistry", "q": "Which gas is commonly used in fire extinguishers because it does not support burning?", "o": ["Oxygen", "Hydrogen", "Carbon dioxide", "Nitrogen dioxide"], "a": 2, "e": "CO₂ is heavier than air and cuts off the oxygen supply to the fire.", "qh": "आग बुझाने वाले यंत्रों में आम तौर पर कौन-सी गैस इस्तेमाल होती है, क्योंकि वह जलने में मदद नहीं करती?", "oh": ["ऑक्सीजन", "हाइड्रोजन", "कार्बन डाइऑक्साइड", "नाइट्रोजन डाइऑक्साइड"], "eh": "CO₂ हवा से भारी होती है और आग तक ऑक्सीजन पहुँचना रोक देती है।", "level": "easy"}, {"s": "General Science", "t": "Chemistry", "q": "German silver is an alloy of:", "o": ["Copper, zinc and nickel", "Silver and copper", "Silver and tin", "Iron and nickel"], "a": 0, "e": "German silver (nickel silver) contains no silver at all.", "qh": "जर्मन सिल्वर किसकी मिश्रधातु है?", "oh": ["तांबा, जस्ता और निकल", "चाँदी और तांबा", "चाँदी और टिन", "लोहा और निकल"], "eh": "जर्मन सिल्वर (निकल सिल्वर) में चाँदी बिल्कुल नहीं होती।", "level": "tough"}, {"s": "General Science", "t": "Physics", "q": "What is the kinetic energy of a 4 kg ball moving at 5 m/s?", "o": ["20 J", "100 J", "10 J", "50 J"], "a": 3, "e": "KE = ½mv² = ½ × 4 × 5² = 50 J.", "qh": "5 m/s से चल रही 4 kg की गेंद की गतिज ऊर्जा क्या है?", "oh": ["20 J", "100 J", "10 J", "50 J"], "eh": "गतिज ऊर्जा = ½mv² = ½ × 4 × 5² = 50 J।", "level": "easy"}, {"s": "General Science", "t": "Biology", "q": "Which mammal lays eggs?", "o": ["Bat", "Duck-billed platypus", "Dolphin", "Kangaroo"], "a": 1, "e": "The platypus and echidnas (monotremes) are the only egg-laying mammals; the kangaroo is a pouched marsupial.", "qh": "कौन-सा स्तनधारी अंडे देता है?", "oh": ["चमगादड़", "डक-बिल्ड प्लैटिपस", "डॉल्फ़िन", "कंगारू"], "eh": "प्लैटिपस और एकिडना (मोनोट्रीम) अंडे देने वाले अकेले स्तनधारी हैं; कंगारू थैलीदार (मार्सुपियल) है।", "level": "tough"}, {"s": "General Science", "t": "Chemistry", "q": "Haematite is an ore of:", "o": ["Copper", "Aluminium", "Zinc", "Iron"], "a": 3, "e": "Haematite (Fe₂O₃) is the main ore of iron.", "qh": "हेमेटाइट किस धातु का अयस्क है?", "oh": ["तांबा", "एल्युमिनियम", "जस्ता", "लोहा"], "eh": "हेमेटाइट (Fe₂O₃) लोहे का मुख्य अयस्क है।", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "Sound waves with frequency below 20 Hz are called:", "o": ["Ultrasonic waves", "Audible waves", "Microwaves", "Infrasonic waves"], "a": 3, "e": "Humans hear about 20 Hz–20 kHz; below 20 Hz is infrasonic and above 20 kHz is ultrasonic.", "qh": "20 Hz से कम आवृत्ति वाली ध्वनि तरंगों को क्या कहते हैं?", "oh": ["पराश्रव्य (अल्ट्रासोनिक) तरंगें", "श्रव्य तरंगें", "सूक्ष्म तरंगें", "अवश्रव्य (इन्फ़्रासोनिक) तरंगें"], "eh": "मनुष्य लगभग 20 Hz–20 kHz सुनते हैं; 20 Hz से कम अवश्रव्य और 20 kHz से ज़्यादा पराश्रव्य है।", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "The upward motion of a rocket is based on:", "o": ["Newton's first law of motion", "Law of gravitation", "Newton's third law of motion", "Archimedes' principle"], "a": 2, "e": "Hot gases are pushed backward and the gases push the rocket forward with an equal and opposite force.", "qh": "रॉकेट का ऊपर जाना किस पर आधारित है?", "oh": ["न्यूटन का गति का पहला नियम", "गुरुत्वाकर्षण का नियम", "न्यूटन का गति का तीसरा नियम", "आर्किमिडीज़ का सिद्धांत"], "eh": "गर्म गैसें पीछे धकेली जाती हैं और गैसें रॉकेट को बराबर और विपरीत बल से आगे धकेलती हैं।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "When water is electrolysed, the volumes of hydrogen and oxygen collected are in the ratio:", "o": ["1 : 2", "2 : 1", "1 : 1", "1 : 8"], "a": 1, "e": "H₂O gives 2H₂ : O₂, so hydrogen is twice the volume of oxygen (the mass ratio is 1 : 8).", "qh": "पानी के विद्युत-अपघटन में एकत्र हाइड्रोजन और ऑक्सीजन के आयतनों का अनुपात क्या होता है?", "oh": ["1 : 2", "2 : 1", "1 : 1", "1 : 8"], "eh": "2H₂O → 2H₂ + O₂, इसलिए हाइड्रोजन का आयतन ऑक्सीजन का दोगुना होता है (द्रव्यमान का अनुपात 1 : 8 है)।", "level": "tough"}, {"s": "General Science", "t": "Biology", "q": "Which metal is present at the centre of the chlorophyll molecule?", "o": ["Magnesium", "Iron", "Copper", "Zinc"], "a": 0, "e": "Chlorophyll has a magnesium ion at its centre; haemoglobin has iron.", "qh": "क्लोरोफ़िल अणु के केंद्र में कौन-सी धातु होती है?", "oh": ["मैग्नीशियम", "लोहा", "तांबा", "जस्ता"], "eh": "क्लोरोफ़िल के केंद्र में मैग्नीशियम आयन होता है; हीमोग्लोबिन में लोहा होता है।", "level": "tough"}, {"s": "General Science", "t": "Biology", "q": "The first vaccine, against smallpox, was developed by:", "o": ["Louis Pasteur", "Alexander Fleming", "Robert Koch", "Edward Jenner"], "a": 3, "e": "Edward Jenner used cowpox material to protect against smallpox in 1796.", "qh": "चेचक (स्मॉलपॉक्स) के खिलाफ़ पहला टीका किसने बनाया?", "oh": ["लुई पाश्चर", "अलेक्ज़ेंडर फ़्लेमिंग", "रॉबर्ट कोच", "एडवर्ड जेनर"], "eh": "एडवर्ड जेनर ने 1796 में काउपॉक्स से चेचक से बचाव का तरीका बनाया।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "Which non-metal is a liquid at room temperature?", "o": ["Bromine", "Iodine", "Chlorine", "Sulphur"], "a": 0, "e": "Bromine is the only non-metal that is liquid at room temperature; mercury is the liquid metal.", "qh": "कौन-सी अधातु कमरे के ताप पर द्रव होती है?", "oh": ["ब्रोमीन", "आयोडीन", "क्लोरीन", "सल्फ़र"], "eh": "ब्रोमीन कमरे के ताप पर द्रव रहने वाली एकमात्र अधातु है; पारा द्रव धातु है।", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "Long-sightedness (hypermetropia) is corrected by using a:", "o": ["Concave lens", "Convex lens", "Cylindrical lens", "Plane glass"], "a": 1, "e": "In hypermetropia the image forms behind the retina; a converging (convex) lens corrects it.", "qh": "दूर-दृष्टि दोष (हाइपरमेट्रोपिया) किस लेंस से ठीक किया जाता है?", "oh": ["अवतल लेंस", "उत्तल लेंस", "बेलनाकार लेंस", "समतल काँच"], "eh": "दूर-दृष्टि दोष में प्रतिबिंब रेटिना के पीछे बनता है; अभिसारी (उत्तल) लेंस इसे ठीक करता है।", "level": "easy"}, {"s": "Mathematics", "t": "Percentage", "q": "The population of a town is 50,000. It increases by 20% every year. What will the population be after 2 years?", "o": ["60,000", "72,000", "70,000", "72,100"], "a": 1, "e": "50,000 × 1.2 × 1.2 = 72,000.", "qh": "एक कस्बे की आबादी 50,000 है। यह हर साल 20% बढ़ती है। 2 साल बाद आबादी कितनी होगी?", "oh": ["60,000", "72,000", "70,000", "72,100"], "eh": "50,000 × 1.2 × 1.2 = 72,000।", "level": "easy"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "What is the fourth proportional to 3, 5 and 12?", "o": ["20", "17", "40", "22"], "a": 0, "e": "3 : 5 = 12 : x → x = 5 × 12/3 = 20.", "qh": "3, 5 और 12 का चौथा समानुपाती क्या है?", "oh": ["20", "17", "40", "22"], "eh": "3 : 5 = 12 : x → x = 5 × 12/3 = 20।", "level": "easy"}, {"s": "Mathematics", "t": "Interest", "q": "What is the simple interest on ₹5,000 at 8% per annum for 3 years?", "o": ["₹400", "₹2,400", "₹1,200", "₹1,600"], "a": 2, "e": "SI = P × R × T/100 = 5000 × 8 × 3/100 = ₹1,200.", "qh": "₹5,000 पर 8% वार्षिक दर से 3 साल का साधारण ब्याज कितना होगा?", "oh": ["₹400", "₹2,400", "₹1,200", "₹1,600"], "eh": "साधारण ब्याज = P × R × T/100 = 5000 × 8 × 3/100 = ₹1,200।", "level": "easy"}, {"s": "Mathematics", "t": "Mensuration", "q": "A rectangular park is 40 m long and 30 m wide. A path 3 m wide runs all around it on the outside. What is the cost of paving the path at ₹20 per m²?", "o": ["₹9,120", "₹7,680", "₹10,120", "₹8,400"], "a": 0, "e": "Path area = (40+6)(30+6) − 40×30 = 456 m². Cost = 456 × 20 = ₹9,120.", "qh": "एक आयताकार पार्क 40 m लंबा और 30 m चौड़ा है। उसके चारों ओर बाहर की तरफ़ 3 m चौड़ा रास्ता है। ₹20 प्रति m² की दर से रास्ता बनवाने का खर्च कितना होगा?", "oh": ["₹9,120", "₹7,680", "₹10,120", "₹8,400"], "eh": "रास्ते का क्षेत्रफल = (40+6)(30+6) − 40×30 = 456 m²। खर्च = 456 × 20 = ₹9,120।", "level": "tough"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "The incomes of Deepak and Suresh are in the ratio 9 : 7 and their expenditures are in the ratio 7 : 4. If each of them saves ₹1,300, what is Deepak's income?", "o": ["₹2,700", "₹4,000", "₹1,700", "₹1,400"], "a": 0, "e": "9x − 7y = 7x − 4y = 1300 → 2x = 3y. Solving: x = 300, y = 200, so income = 9 × 300 = ₹2,700.", "qh": "दीपक और सुरेश की आय का अनुपात 9 : 7 और खर्च का अनुपात 7 : 4 है। अगर दोनों ₹1,300 बचाते हैं, तो दीपक की आय कितनी है?", "oh": ["₹2,700", "₹4,000", "₹1,700", "₹1,400"], "eh": "9x − 7y = 7x − 4y = 1300 → 2x = 3y। हल करने पर x = 300, y = 200, आय = 9 × 300 = ₹2,700।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "Manoj bought a second-hand refrigerator for ₹5,500 and spent ₹300 on repairs. He sold it for ₹6,496. What is his profit percentage?", "o": ["17%", "12%", "18%", "18 6/55%"], "a": 1, "e": "Total CP = ₹5,500 + ₹300 = ₹5,800; profit = ₹696; profit % = ₹696/₹5,800 × 100 = 12%.", "qh": "मनोज ने एक पुराना फ़्रिज ₹5,500 में खरीदा और ₹300 मरम्मत पर खर्च किए। उसने इसे ₹6,496 में बेचा। उसका लाभ प्रतिशत क्या है?", "oh": ["17%", "12%", "18%", "18 6/55%"], "eh": "कुल क्रय मूल्य = ₹5,500 + ₹300 = ₹5,800; लाभ = ₹696; लाभ % = ₹696/₹5,800 × 100 = 12%।", "level": "easy"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: √625 + √36 × ∛125 = ?", "o": ["54", "36", "55", "60"], "a": 2, "e": "√625 = 25, √36 = 6, ∛125 = 5; 25 + 6 × 5 = 55.", "qh": "सरल कीजिए: √625 + √36 × ∛125 = ?", "oh": ["54", "36", "55", "60"], "eh": "√625 = 25, √36 = 6, ∛125 = 5; 25 + 6 × 5 = 55।", "level": "medium"}, {"s": "Mathematics", "t": "Mensuration", "q": "What is the volume of a cone with radius 14 cm and height 12 cm? (Take π = 22/7)", "o": ["3696 cm³", "2420 cm³", "1232 cm³", "2464 cm³"], "a": 3, "e": "⅓πr²h = ⅓ × 22/7 × 14² × 12 = 2464 cm³.", "qh": "14 cm त्रिज्या और ऊँचाई 12 cm वाले शंकु का आयतन कितना है? (π = 22/7 लें)", "oh": ["3696 cm³", "2420 cm³", "1232 cm³", "2464 cm³"], "eh": "⅓πr²h = ⅓ × 22/7 × 14² × 12 = 2464 cm³।", "level": "medium"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A boat whose speed in still water is 15 km/h goes some distance downstream and comes back upstream in 5 hours in all. If the stream flows at 3 km/h, what is the one-way distance?", "o": ["37.5 km", "41 km", "45 km", "36 km"], "a": 3, "e": "D/18 + D/12 = 5 → D = 5 × 18 × 12/30 = 36 km.", "qh": "शांत पानी में 15 km/h की रफ़्तार वाली एक नाव धारा के साथ कुछ दूरी जाकर धारा के उलटे लौटती है, कुल 5 घंटे में। धारा की रफ़्तार 3 km/h हो, तो एक तरफ़ की दूरी कितनी है?", "oh": ["37.5 km", "41 km", "45 km", "36 km"], "eh": "D/18 + D/12 = 5 → D = 5 × 18 × 12/30 = 36 km।", "level": "medium"}, {"s": "Mathematics", "t": "Number System", "q": "Students of a school stand in rows of 5, 6 and 8; each time 1 students are left without a row. Find the least possible number of students.", "o": ["121", "241", "122", "119"], "a": 0, "e": "LCM(5, 6, 8) = 120; number = 120 + 1 = 121.", "qh": "एक स्कूल के छात्र 5, 6 और 8 की पंक्तियों में खड़े होते हैं; हर बार 1 छात्र किसी पंक्ति में नहीं आ पाते। छात्रों की कम से कम संभव संख्या बताइए।", "oh": ["121", "241", "122", "119"], "eh": "LCM(5, 6, 8) = 120; संख्या = 120 + 1 = 121।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "What is the remainder when 963 × 829 is divided by 13?", "o": ["0", "12", "11", "10"], "a": 3, "e": "963 mod 13 = 1, 829 mod 13 = 10; 1 × 10 = 10; remainder = 10.", "qh": "963 × 829 को 13 से भाग देने पर शेषफल क्या होगा?", "oh": ["0", "12", "11", "10"], "eh": "963 का शेष 1, 829 का शेष 10; 1 × 10 = 10; शेषफल = 10।", "level": "medium"}, {"s": "Mathematics", "t": "Percentage", "q": "The population of a town is 25,000. It increases by 10% in the first year and decreases by 5% in the second year. What is the population after 2 years?", "o": ["26,125", "27,500", "26,225", "25,925"], "a": 0, "e": "25,000 × 1.1 × 0.95 = 26,125.", "qh": "एक कस्बे की आबादी 25,000 है। यह पहले साल 10% बढ़ती है और दूसरे साल 5% घटती है। 2 साल बाद आबादी कितनी होगी?", "oh": ["26,125", "27,500", "26,225", "25,925"], "eh": "25,000 × 1.1 × 0.95 = 26,125।", "level": "tough"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 7 consecutive even numbers is 64. What is the smallest of them?", "o": ["56", "71", "60", "58"], "a": 3, "e": "The average is the middle number 64; there are 3 numbers on each side with gap 2 → smallest = 58.", "qh": "7 लगातार सम संख्याओं का औसत 64 है। उनमें सबसे छोटी संख्या कौन-सी है?", "oh": ["56", "71", "60", "58"], "eh": "औसत ही बीच वाली संख्या 64 है; दोनों ओर 3 संख्याएँ, अंतर 2 → उत्तर = 58।", "level": "easy"}, {"s": "Mathematics", "t": "Time and Work", "q": "Ravi and Vikas can finish a work in 10 days and 15 days respectively. They work together for 5 days and then Ravi leaves. In how many days in total will the work be finished?", "o": ["6.5 days", "7.5 days", "6 days", "8.5 days"], "a": 1, "e": "In 5 days: 5 × (1/10 + 1/15) = 5/6 done. Left 1/6 is done by Vikas in 2.5 days. Total = 7.5 days.", "qh": "रवि और विकास एक काम क्रमशः 10 दिन और 15 दिन में पूरा कर सकते हैं। दोनों 5 दिन साथ काम करते हैं और फिर रवि काम छोड़ देता है। काम कुल कितने दिन में पूरा होगा?", "oh": ["6.5 दिन", "7.5 दिन", "6 दिन", "8.5 दिन"], "eh": "5 दिन में: 5 × (1/10 + 1/15) = 5/6 काम हुआ। बचा 1/6 काम अकेले विकास से 2.5 दिन में होता है। कुल = 7.5 दिन।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "Rahul starts a business with ₹20,000. After 8 months Arjun joins with ₹36,000, and 8 months after the start Deepak joins with ₹60,000. Out of an annual profit of ₹13,000, what is Arjun's share?", "o": ["₹2,000", "₹3,000", "₹5,000", "₹4,000"], "a": 1, "e": "Capital × months = 20000×12 : 36000×4 : 60000×4 = 5 : 3 : 5. Share = 3/13 × ₹13,000 = ₹3,000.", "qh": "राहुल ₹20,000 से कारोबार शुरू करता है। 8 महीने बाद अर्जुन ₹36,000 लेकर जुड़ता है, और शुरुआत से 8 महीने बाद दीपक ₹60,000 लेकर जुड़ता है। साल के ₹13,000 लाभ में अर्जुन का हिस्सा कितना है?", "oh": ["₹2,000", "₹3,000", "₹5,000", "₹4,000"], "eh": "पूँजी × महीने = 20000×12 : 36000×4 : 60000×4 = 5 : 3 : 5। हिस्सा = 3/13 × ₹13,000 = ₹3,000।", "level": "tough"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A shopkeeper gives a discount of 25% on the marked price of a study table and still makes a profit of 35%. If its cost price is ₹420, what is the marked price?", "o": ["₹672", "₹716", "₹756", "₹816"], "a": 2, "e": "SP = ₹420 × 135/100 = ₹567; MP = SP × 100/75 = ₹756.", "qh": "एक दुकानदार एक पढ़ाई की मेज़ के अंकित मूल्य पर 25% छूट देता है और फिर भी 35% लाभ कमाता है। अगर इसका क्रय मूल्य ₹420 है, तो अंकित मूल्य क्या है?", "oh": ["₹672", "₹716", "₹756", "₹816"], "eh": "विक्रय मूल्य = ₹420 × 135/100 = ₹567; अंकित मूल्य = विक्रय मूल्य × 100/75 = ₹756।", "level": "easy"}, {"s": "Mathematics", "t": "Algebra", "q": "The cost of 4 pens and 5 notebooks is ₹156, and the cost of 2 pens and 3 notebooks is ₹88. What is the cost of one notebook?", "o": ["₹17", "₹22", "₹20", "₹14"], "a": 2, "e": "4p + 5n = 156, 2p + 3n = 88. Eliminating p: n = (4×88 − 2×156)/(4×3 − 2×5) = ₹20; pen = ₹14.", "qh": "4 पेन और 5 कॉपियों का दाम ₹156 है, और 2 पेन और 3 कॉपियों का दाम ₹88 है। एक कॉपी का दाम कितना है?", "oh": ["₹17", "₹22", "₹20", "₹14"], "eh": "4p + 5n = 156, 2p + 3n = 88। p हटाने पर: n = (4×88 − 2×156)/(4×3 − 2×5) = ₹20; पेन = ₹14।", "level": "easy"}, {"s": "Mathematics", "t": "Trigonometry", "q": "If sin θ = 5/13, what is the value of cos²θ − sin²θ? (θ is acute)", "o": ["7/13", "119/169", "1", "144/169"], "a": 1, "e": "cos θ = 12/13. cos²θ − sin²θ = (144 − 25)/169 = 119/169.", "qh": "अगर sin θ = 5/13 है, तो cos²θ − sin²θ का मान क्या है? (θ न्यून कोण है)", "oh": ["7/13", "119/169", "1", "144/169"], "eh": "cos θ = 12/13. cos²θ − sin²θ = (144 − 25)/169 = 119/169।", "level": "tough"}, {"s": "Mathematics", "t": "Time and Work", "q": "Pipes A and B can fill a tank in 12 hours and 15 hours, while pipe C can empty the full tank in 40 hours. If all three are opened together on an empty tank, in how many hours will it be full?", "o": ["7 hours", "8 hours", "16 hours", "26/3 hours"], "a": 1, "e": "Net per hour = 1/12 + 1/15 − 1/40 = 1/8 → 8 hours.", "qh": "पाइप A और B एक टंकी को 12 घंटे और 15 घंटे में भरते हैं, जबकि पाइप C भरी टंकी को 40 घंटे में खाली करता है। खाली टंकी पर तीनों एक साथ खोलने पर टंकी कितने घंटे में भरेगी?", "oh": ["7 घंटे", "8 घंटे", "16 घंटे", "26/3 घंटे"], "eh": "हर घंटे कुल भराई = 1/12 + 1/15 − 1/40 = 1/8 → 8 घंटे।", "level": "tough"}, {"s": "Mathematics", "t": "Geometry", "q": "A 5 m long ladder is placed against a vertical wall. Its foot is 4 m from the wall. How high up the wall does the ladder reach?", "o": ["3 m", "5 m", "4 m", "1 m"], "a": 0, "e": "h = √(5² − 4²) = √9 = 3 m.", "qh": "5 m लंबी एक सीढ़ी एक सीधी दीवार से टिकाई गई है। उसका निचला सिरा दीवार से 4 m दूर है। सीढ़ी दीवार पर कितनी ऊँचाई तक पहुँचती है?", "oh": ["3 m", "5 m", "4 m", "1 m"], "eh": "ऊँचाई = √(5² − 4²) = √9 = 3 m।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "By selling 20 notebooks, a trader gains the selling price of 8 notebooks. What is his gain percentage?", "o": ["28 4/7%", "40%", "66 2/3%", "71 2/3%"], "a": 2, "e": "Gain = SP of 8, so CP of 20 = SP of 12. Gain % = 8/12 × 100 = 66 2/3%.", "qh": "20 कॉपियाँ बेचकर एक व्यापारी को 8 कॉपियाँ के विक्रय मूल्य के बराबर लाभ होता है। उसका लाभ प्रतिशत क्या है?", "oh": ["28 4/7%", "40%", "66 2/3%", "71 2/3%"], "eh": "लाभ = 8 का विक्रय मूल्य, इसलिए 20 का क्रय मूल्य = 12 का विक्रय मूल्य। लाभ % = 8/12 × 100 = 66 2/3%।", "level": "medium"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 9 consecutive even numbers is 68. What is the largest of them?", "o": ["76", "74", "77", "78"], "a": 0, "e": "The average is the middle number 68; there are 4 numbers on each side with gap 2 → largest = 76.", "qh": "9 लगातार सम संख्याओं का औसत 68 है। उनमें सबसे बड़ी संख्या कौन-सी है?", "oh": ["76", "74", "77", "78"], "eh": "औसत ही बीच वाली संख्या 68 है; दोनों ओर 4 संख्याएँ, अंतर 2 → उत्तर = 76।", "level": "medium"}, {"s": "Mathematics", "t": "Ages", "q": "The present ages of Ravi and Deepak are in the ratio 2 : 3. After 8 years, the ratio will be 4 : 5. What is Deepak's present age?", "o": ["8 years", "20 years", "4 years", "12 years"], "a": 3, "e": "(2x + 8)/(3x + 8) = 4/5 → x = 4; age = 3 × 4 = 12 years.", "qh": "रवि और दीपक की अभी की आयु का अनुपात 2 : 3 है। 8 साल बाद यह अनुपात 4 : 5 हो जाएगा। दीपक की अभी की आयु कितनी है?", "oh": ["8 साल", "20 साल", "4 साल", "12 साल"], "eh": "(2x + 8)/(3x + 8) = 4/5 → x = 4; आयु = 3 × 4 = 12 साल।", "level": "tough"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: 40% of 440 − 20% of 570 = ?", "o": ["290", "62", "72", "57"], "a": 1, "e": "40% of 440 = 176; 20% of 570 = 114; result = 62.", "qh": "सरल कीजिए: 440 का 40% − 570 का 20% = ?", "oh": ["290", "62", "72", "57"], "eh": "440 का 40% = 176; 570 का 20% = 114; परिणाम = 62।", "level": "tough"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "Two buses start at the same time from Patna and Gaya, 420 km apart, and travel towards each other at 50 km/h and 40 km/h. After how much time will they meet?", "o": ["5 h 40 min", "5 h 10 min", "4 h 10 min", "4 h 40 min"], "a": 3, "e": "Relative speed = 50 + 40 = 90 km/h; time = 420/90 h = 4 h 40 min.", "qh": "दो बसें एक साथ पटना और गया से, जो 420 km दूर हैं, एक-दूसरे की ओर 50 km/h और 40 km/h की चाल से चलती हैं। कितने समय बाद वे मिलेंगी?", "oh": ["5 घंटे 40 मिनट", "5 घंटे 10 मिनट", "4 घंटे 10 मिनट", "4 घंटे 40 मिनट"], "eh": "सापेक्ष चाल = 50 + 40 = 90 km/h; समय = 420/90 घंटे = 4 घंटे 40 मिनट।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "H, W, T, S, K, L, B and A are sitting around a circular table, all facing the centre.\nT sits immediately to the right of H.\nL is an immediate neighbour of W.\nH sits second to the right of B.\nW sits opposite K.\nA sits second to the left of L.\nWho sits opposite L?", "o": ["A", "B", "S", "H"], "a": 3, "e": "Only one arrangement fits. Going to the right (anticlockwise) from L: L → S → B → K → H → T → A → W. Answer: H.", "qh": "H, W, T, S, K, L, B और A एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nT, H के ठीक दाईं ओर बैठा है।\nL, W का ठीक पड़ोसी है।\nH, B के दाईं ओर दूसरे स्थान पर बैठा है।\nW, K के ठीक सामने बैठा है।\nA, L के बाईं ओर दूसरे स्थान पर बैठा है।\nL के ठीक सामने कौन बैठा है?", "oh": ["A", "B", "S", "H"], "eh": "केवल एक व्यवस्था बैठती है। L से दाईं ओर (घड़ी की उलटी दिशा में) चलें: L → S → B → K → H → T → A → W। उत्तर: H।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nAYFV : EBJT :: TYPS : ?", "o": ["QTBX", "PVLU", "XBTQ", "XBTR"], "a": 2, "e": "Each letter moves +4, +3, +4, -2 in order. TYPS → XBTQ.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nAYFV : EBJT :: TYPS : ?", "oh": ["QTBX", "PVLU", "XBTQ", "XBTR"], "eh": "हर अक्षर क्रम से +4, +3, +4, -2 खिसकता है। TYPS → XBTQ।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "Study the following series of digits and answer the question.\n9 5 5 4 8 7 5 6 9 4 8 6 8 1 1 3 5 1 9 7 8 6 9 6 7\nHow many 5s are there, each of which is immediately preceded by an odd digit and immediately followed by an even digit?", "o": ["2", "5", "3", "1"], "a": 0, "e": "Matching groups: 5 5 4, 7 5 6 → 2.", "qh": "नीचे दी गई अंकों की शृंखला पढ़कर प्रश्न का उत्तर दीजिए।\n9 5 5 4 8 7 5 6 9 4 8 6 8 1 1 3 5 1 9 7 8 6 9 6 7\nऐसे कितने 5 हैं, जिनके ठीक पहले विषम अंक और ठीक बाद सम अंक है?", "oh": ["2", "5", "3", "1"], "eh": "शर्त पूरी करने वाले समूह: 5 5 4, 7 5 6 → 2।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n3 J O + £ G © H # + O N 3 © 8 6 M S N 5 + ©\nHow many numbers are there in the arrangement, each of which is immediately preceded by a letter and immediately followed by a symbol?", "o": ["1", "3", "2", "4"], "a": 2, "e": "Matching places: N3©, N5+ → 2.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n3 J O + £ G © H # + O N 3 © 8 6 M S N 5 + ©\nइस क्रम में ऐसी कितनी संख्याएँ हैं, जिनके ठीक पहले एक अक्षर और ठीक बाद एक चिह्न है?", "oh": ["1", "3", "2", "4"], "eh": "शर्त पूरी करने वाले स्थान: N3©, N5+ → 2।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '−', '−' means '+', '×' means '÷', '÷' means '×', then what is the value of the following expression?\n26 ÷ 29 − 20 = ?", "o": ["774", "784", "776", "1548"], "a": 0, "e": "Replace the signs: 26 × 29 + 20 = 774 (using BODMAS).", "qh": "अगर '+' का मतलब '−', '−' का मतलब '+', '×' का मतलब '÷', '÷' का मतलब '×' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n26 ÷ 29 − 20 = ?", "oh": ["774", "784", "776", "1548"], "eh": "चिह्न बदलें: 26 × 29 + 20 = 774 (BODMAS से)।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nFish : Gills :: Human : ?", "o": ["Heart", "Nose", "Skin", "Lungs"], "a": 3, "e": "Relation: 'breathes through'. Fish – Gills, so Human – Lungs.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nमछली : गलफड़े :: इंसान : ?", "oh": ["दिल", "नाक", "त्वचा", "फेफड़े"], "eh": "संबंध: 'से साँस लेता है'। मछली – गलफड़े, इसलिए इंसान – फेफड़े।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'MANGO' is coded as 53. How will 'SPOON' be coded in that language?", "o": ["87", "82", "83", "79"], "a": 1, "e": "Code = sum of letter positions + 3. For SPOON: 82.", "qh": "एक कोड भाषा में 'MANGO' को 53 लिखा जाता है। उसी भाषा में 'SPOON' को कैसे लिखा जाएगा?", "oh": ["87", "82", "83", "79"], "eh": "कोड = अक्षरों की स्थितियों का योग + 3। SPOON के लिए: 82।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nNo roses are stars.\nAll stars are bottles.\nConclusions:\nI. No stars are roses.\nII. Some bottles are not roses.", "o": ["Only conclusion II follows", "Only conclusion I follows", "Neither I nor II follows", "Both I and II follow"], "a": 3, "e": "Both conclusions are true in every possible diagram.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकोई भी गुलाब तारे नहीं है।\nसभी तारे बोतलें हैं।\nनिष्कर्ष:\nI. कोई भी तारे गुलाब नहीं है।\nII. कुछ बोतलें गुलाब नहीं हैं।", "oh": ["केवल निष्कर्ष II सही है", "केवल निष्कर्ष I सही है", "न I सही है, न II", "I और II दोनों सही हैं"], "eh": "दोनों निष्कर्ष हर संभव आरेख में सही हैं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n# @ * % 9 B D # Q # & 8 $ 1 & £ % 1\nHow many symbols are there in the arrangement, each of which is immediately preceded by a number?", "o": ["4", "3", "2", "5"], "a": 2, "e": "Matching places: 8$1, 1&£ → 2.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n# @ * % 9 B D # Q # & 8 $ 1 & £ % 1\nइस क्रम में ऐसे कितने चिह्न हैं, जिनके ठीक पहले एक संख्या है?", "oh": ["4", "3", "2", "5"], "eh": "शर्त पूरी करने वाले स्थान: 8$1, 1&£ → 2।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "'A @ B' means 'A is the sister of B'; 'A % B' means 'A is the husband of B'; 'A ÷ B' means 'A is the wife of B'; 'A × B' means 'A is the daughter of B'. If G × Q % V @ E, how is G related to E?", "o": ["Mother", "Aunt", "Niece", "Granddaughter"], "a": 2, "e": "Decode: G is the daughter of Q; Q is the husband of V; V is the sister of E. So G is the niece of E.", "qh": "'A @ B' का अर्थ है 'A, B की बहन है'; 'A % B' का अर्थ है 'A, B का पति है'; 'A ÷ B' का अर्थ है 'A, B की पत्नी है'; 'A × B' का अर्थ है 'A, B की बेटी है'। अगर G × Q % V @ E, तो G का E से क्या संबंध है?", "oh": ["माँ", "बुआ/मौसी/चाची", "भतीजी/भांजी", "पोती/नातिन"], "eh": "अर्थ निकालें: G, Q की बेटी; Q, V का पति; V, E की बहन। इसलिए G, E की भतीजी/भांजी है।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "C, S, J, T, H, K and Q are sitting in a row, all facing North.\nExactly 1 person sits between K and H.\nExactly 3 persons sit between K and J.\nExactly 2 persons sit between T and K.\nQ sits second to the right of T.\nH is an immediate neighbour of Q.\nExactly 5 persons sit between S and C.\nJ is an immediate neighbour of C.\nHow many persons sit between Q and T?", "o": ["2", "1", "0", "3"], "a": 1, "e": "Only one order fits all clues (left to right): C J T H Q K S. Answer: 1.", "qh": "C, S, J, T, H, K और Q एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nK और H के बीच ठीक 1 व्यक्ति बैठे हैं।\nK और J के बीच ठीक 3 व्यक्ति बैठे हैं।\nT और K के बीच ठीक 2 व्यक्ति बैठे हैं।\nQ, T के दाईं ओर दूसरे स्थान पर बैठा है।\nH, Q का ठीक पड़ोसी है।\nS और C के बीच ठीक 5 व्यक्ति बैठे हैं।\nJ, C का ठीक पड़ोसी है।\nQ और T के बीच कितने व्यक्ति बैठे हैं?", "oh": ["2", "1", "0", "3"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): C J T H Q K S। उत्तर: 1।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Clock (Mirror Image)", "q": "A clock shows the time 1:10. What time will its mirror image show?", "o": ["11:50", "9:50", "11:00", "10:50"], "a": 3, "e": "Mirror time = 11:60 − 1:10 = 10:50.", "qh": "एक घड़ी 1:10 का समय दिखा रही है। दर्पण में उसका प्रतिबिंब कौन-सा समय दिखाएगा?", "oh": ["11:50", "9:50", "11:00", "10:50"], "eh": "दर्पण का समय = 11:60 − 1:10 = 10:50।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "The following questions are based on the five three-digit numbers given below.\n321   583   783   736   924\nIf the first and the third digits of each number are interchanged, what will be the sum of the digits of the largest number so formed?", "o": ["16", "17", "15", "14"], "a": 0, "e": "After swapping: 123, 385, 387, 637, 429. Largest = 637; digit sum = 16.", "qh": "नीचे दी गई पाँच तीन-अंकीय संख्याओं के आधार पर प्रश्न का उत्तर दीजिए।\n321   583   783   736   924\nअगर हर संख्या के पहले और तीसरे अंक आपस में बदल दिए जाएँ, तो बनी हुई सबसे बड़ी संख्या के अंकों का योग क्या होगा?", "oh": ["16", "17", "15", "14"], "eh": "अदला-बदली के बाद: 123, 385, 387, 637, 429। सबसे बड़ी = 637; अंकों का योग = 16।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["Bat", "Parrot", "Sparrow", "Crow"], "a": 0, "e": "Bat is a mammal; the others are birds.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["चमगादड़", "तोता", "गौरैया", "कौआ"], "eh": "चमगादड़ स्तनधारी है; बाकी पक्षी हैं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nD8Z, F16X, H32V, J64T, ?", "o": ["K128Q", "L127R", "L128R", "M128R"], "a": 2, "e": "First letter +2; number: double each time; last letter -2. So ? = L128R.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nD8Z, F16X, H32V, J64T, ?", "oh": ["K128Q", "L127R", "L128R", "M128R"], "eh": "पहला अक्षर +2; संख्या: हर बार दोगुना; आखिरी अक्षर -2। इसलिए ? = L128R।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n5, 6, 14, 45, 184, ?", "o": ["923", "930", "928", "925"], "a": 3, "e": "Rule: ×1 + 1, ×2 + 2, ×3 + 3, … So ? = 925.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n5, 6, 14, 45, 184, ?", "oh": ["923", "930", "928", "925"], "eh": "नियम: ×1 + 1, ×2 + 2, ×3 + 3, … इसलिए ? = 925।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["ILMQ", "HLMQ", "GKLP", "AEFJ"], "a": 0, "e": "In HLMQ, GKLP, AEFJ the gaps are +4, +1, +4; in ILMQ they are +3, +1, +4.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["ILMQ", "HLMQ", "GKLP", "AEFJ"], "eh": "HLMQ, GKLP, AEFJ में अंतर +4, +1, +4 है; ILMQ में +3, +1, +4 है।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'GLASS' is written as 'INCUU'. How will 'PLANT' be written in that language?", "o": ["VPCNR", "SODQW", "RNCPV", "NRCPV"], "a": 2, "e": "Rule: each letter moves +2. Applying it to PLANT gives RNCPV.", "qh": "एक कोड भाषा में 'GLASS' को 'INCUU' लिखा जाता है। उसी भाषा में 'PLANT' को कैसे लिखा जाएगा?", "oh": ["VPCNR", "SODQW", "RNCPV", "NRCPV"], "eh": "नियम: हर अक्षर +2 खिसकता है। PLANT पर लगाने से RNCPV मिलता है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Puzzle", "q": "7 boxes P, U, X, R, S, T and Q are kept one above the other (not necessarily in this order).\nExactly 4 boxes are placed between boxes Q and P.\nExactly 1 box is placed between boxes Q and S.\nBox T is 5th from the bottom.\nBox Q is 1st from the bottom.\nExactly 1 box is placed between boxes R and P.\nBox S is neither at the top nor at the bottom.\nBox U is 7th from the bottom.\nWhich box is immediately below box R?", "o": ["X", "T", "S", "Q"], "a": 2, "e": "Only one order fits (bottom to top): Q X S R T P U. Answer: S.", "qh": "7 डिब्बे P, U, X, R, S, T और Q एक के ऊपर एक रखे हैं (ज़रूरी नहीं कि इसी क्रम में)।\nडिब्बे Q और P के बीच ठीक 4 डिब्बे रखे हैं।\nडिब्बे Q और S के बीच ठीक 1 डिब्बे रखे हैं।\nडिब्बा T नीचे से 5वें स्थान पर है।\nडिब्बा Q नीचे से 1वें स्थान पर है।\nडिब्बे R और P के बीच ठीक 1 डिब्बे रखे हैं।\nडिब्बा S न सबसे ऊपर है, न सबसे नीचे।\nडिब्बा U नीचे से 7वें स्थान पर है।\nडिब्बे R के ठीक नीचे कौन-सा डिब्बा है?", "oh": ["X", "T", "S", "Q"], "eh": "केवल एक क्रम बैठता है (नीचे से ऊपर): Q X S R T P U। उत्तर: S।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nH9Z, K14W, N19T, Q24Q, ?", "o": ["T29N", "U29N", "T28N", "T31N"], "a": 0, "e": "First letter +3; number: add 5; last letter -3. So ? = T29N.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nH9Z, K14W, N19T, Q24Q, ?", "oh": ["T29N", "U29N", "T28N", "T31N"], "eh": "पहला अक्षर +3; संख्या: 5 जोड़ें; आखिरी अक्षर -3। इसलिए ? = T29N।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Ranking", "q": "In a row of 57 people, Ajay is 10th from the left and Rohit is 8th from the right. How many people are there between them?", "o": ["40", "37", "39", "38"], "a": 2, "e": "Rohit is 50th from the left. Between = 50 − 10 − 1 = 39.", "qh": "57 लोगों की पंक्ति में अजय बाएँ से 10वें और रोहित दाएँ से 8वें स्थान पर है। दोनों के बीच कितने लोग हैं?", "oh": ["40", "37", "39", "38"], "eh": "रोहित बाएँ से 50वें स्थान पर है। बीच में = 50 − 10 − 1 = 39।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n£ 9 E T 5 @ R # $ 8 M 5 J $ $ 4 T S * @ S 8\nHow many odd numbers are there in the arrangement, each of which is immediately preceded by a symbol?", "o": ["2", "4", "3", "1"], "a": 3, "e": "Matching places: £9E → 1.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n£ 9 E T 5 @ R # $ 8 M 5 J $ $ 4 T S * @ S 8\nइस क्रम में ऐसी कितनी विषम संख्याएँ हैं, जिनके ठीक पहले एक चिह्न है?", "oh": ["2", "4", "3", "1"], "eh": "शर्त पूरी करने वाले स्थान: £9E → 1।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "P, G, E, B, A and V are sitting in a row, all facing North.\nP sits immediately to the right of E.\nP does not sit at either end.\nG sits at one of the ends.\nE sits immediately to the right of V.\nExactly 3 persons sit between P and B.\nHow many persons sit between G and E?", "o": ["0", "1", "4", "3"], "a": 1, "e": "Only one order fits all clues (left to right): B A V E P G. Answer: 1.", "qh": "P, G, E, B, A और V एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nP, E के ठीक दाईं ओर बैठा है।\nP किसी भी छोर पर नहीं बैठा है।\nG किसी एक छोर पर बैठा है।\nE, V के ठीक दाईं ओर बैठा है।\nP और B के बीच ठीक 3 व्यक्ति बैठे हैं।\nG और E के बीच कितने व्यक्ति बैठे हैं?", "oh": ["0", "1", "4", "3"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): B A V E P G। उत्तर: 1।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nAll kites are cups.\nNo cups are coins.\nConclusions:\nI. Some kites are coins.\nII. Some cups are not kites.", "o": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "a": 3, "e": "Each conclusion fails in at least one possible diagram, and they do not form an either–or pair.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nसभी पतंगें कप हैं।\nकोई भी कप सिक्के नहीं है।\nनिष्कर्ष:\nI. कुछ पतंगें सिक्के हैं।\nII. कुछ कप पतंगें नहीं हैं।", "oh": ["केवल निष्कर्ष I सही है", "केवल निष्कर्ष II सही है", "I और II दोनों सही हैं", "न I सही है, न II"], "eh": "हर निष्कर्ष किसी न किसी आरेख में गलत हो जाता है, और ये 'या तो–या' वाली जोड़ी नहीं हैं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nIAU, KYS, MWQ, OUO, ?", "o": ["SSM", "QSM", "QUM", "QSO"], "a": 1, "e": "Letter positions move by +2, −2, −2 (for 1st, 2nd, 3rd letters). So ? = QSM.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nIAU, KYS, MWQ, OUO, ?", "oh": ["SSM", "QSM", "QUM", "QSO"], "eh": "अक्षरों की स्थिति +2, −2, −2 से बदलती है (पहले, दूसरे, तीसरे अक्षर के लिए)। इसलिए ? = QSM।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Ravi is facing North. Ravi turns 45° clockwise, then 45° anticlockwise, then 135° clockwise. Which direction is Ravi facing now?", "o": ["South-West", "North-East", "South-East", "North-West"], "a": 2, "e": "Net turn = 135° (clockwise 135°). From North this gives South-East.", "qh": "रवि का मुँह उत्तर की ओर है। रवि 45° दक्षिणावर्त, फिर 45° वामावर्त, फिर 135° दक्षिणावर्त घूमता/घूमती है। अब उसका मुँह किस दिशा में है?", "oh": ["दक्षिण-पश्चिम", "उत्तर-पूर्व", "दक्षिण-पूर्व", "उत्तर-पश्चिम"], "eh": "कुल घुमाव = 135°। उत्तर से यह दक्षिण-पूर्व देता है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n5, 29, 11, 26, 17, 23, ?", "o": ["46", "21", "23", "24"], "a": 2, "e": "Rule: Two series alternate: 5, 11, … (+6) and 29, 26, … (−3). So ? = 23.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n5, 29, 11, 26, 17, 23, ?", "oh": ["46", "21", "23", "24"], "eh": "नियम: दो शृंखलाएँ बारी-बारी से: 5, 11, … (+6) और 29, 26, … (−3)। इसलिए ? = 23।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Karan starts from point P, walks 4 km towards North, then turns right and walks 2 km, then turns right and walks 8 km. In which direction is Karan now with respect to point P?", "o": ["South-East", "North-West", "North", "West"], "a": 0, "e": "Net East–West = +2 km, net North–South = -4 km; direction = South-East.", "qh": "करण बिंदु P से शुरू करके उत्तर की ओर 4 km चलता है, फिर दाएँ मुड़कर 2 km चलता है, फिर दाएँ मुड़कर 8 km चलता है। अब करण बिंदु P से किस दिशा में है?", "oh": ["दक्षिण-पूर्व", "उत्तर-पश्चिम", "उत्तर", "पश्चिम"], "eh": "कुल पूर्व–पश्चिम = +2 km, कुल उत्तर–दक्षिण = -4 km; दिशा = दक्षिण-पूर्व।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\n13 : 2184 :: 9 : ?", "o": ["738", "81", "720", "711"], "a": 2, "e": "Rule: x → x³ − x. 13 → 2184, so 9 → 720.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\n13 : 2184 :: 9 : ?", "oh": ["738", "81", "720", "711"], "eh": "नियम: x → x³ − x। 13 → 2184, इसलिए 9 → 720।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nPen : Write :: Knife : ?", "o": ["Cut", "Sharp", "Kitchen", "Steel"], "a": 0, "e": "Relation: 'is used to'. Pen – Write, so Knife – Cut.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nपेन : लिखना :: चाकू : ?", "oh": ["काटना", "तेज़", "रसोई", "स्टील"], "eh": "संबंध: 'से किया जाता है'। पेन – लिखना, इसलिए चाकू – काटना।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "History", "q": "In the Second Battle of Tarain (1192), Muhammad Ghori defeated:", "o": ["Jaichand", "Anangpal Tomar", "Rana Sanga", "Prithviraj Chauhan"], "a": 3, "e": "Ghori lost the First Battle of Tarain (1191) but defeated Prithviraj Chauhan in 1192, opening north India to Turkish rule.", "qh": "तराइन के दूसरे युद्ध (1192) में मुहम्मद गोरी ने किसे हराया?", "oh": ["जयचंद", "अनंगपाल तोमर", "राणा सांगा", "पृथ्वीराज चौहान"], "eh": "गोरी 1191 में तराइन का पहला युद्ध हारा, पर 1192 में पृथ्वीराज चौहान को हराया, जिससे उत्तर भारत में तुर्क शासन का रास्ता खुला।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Geography", "q": "Laterite soil is formed mainly by:", "o": ["Deposition by rivers in deltas", "Leaching in areas of high temperature and heavy rainfall", "Wind deposition in deserts", "Weathering of basalt in dry areas"], "a": 1, "e": "Heavy rain washes away silica and lime, leaving iron and aluminium oxides; such soil is found in the Western Ghats, Odisha and the North-East.", "qh": "लेटराइट मिट्टी मुख्य रूप से कैसे बनती है?", "oh": ["डेल्टा में नदियों के जमाव से", "ऊँचे तापमान और भारी वर्षा वाले क्षेत्रों में निक्षालन (लीचिंग) से", "रेगिस्तान में हवा के जमाव से", "शुष्क क्षेत्रों में बेसाल्ट के अपक्षय से"], "eh": "भारी वर्षा सिलिका और चूना बहा ले जाती है और लोहे व एल्युमिनियम के ऑक्साइड बचते हैं; यह मिट्टी पश्चिमी घाट, ओडिशा और पूर्वोत्तर में मिलती है।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Art & Culture", "q": "Ghoomar is a folk dance of:", "o": ["Punjab", "Assam", "Kerala", "Rajasthan"], "a": 3, "e": "Ghoomar is performed by women of Rajasthan in swirling ghagras.", "qh": "घूमर किस राज्य का लोक नृत्य है?", "oh": ["पंजाब", "असम", "केरल", "राजस्थान"], "eh": "घूमर राजस्थान की महिलाएँ घूमते घाघरों में करती हैं।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Economy", "q": "In its October 2026 World Economic Outlook, the IMF projected India's growth for 2026 (FY 2026-27) at:", "o": ["6.4%", "5.8%", "7.0%", "8.2%"], "a": 2, "e": "The IMF raised India's 2026 growth forecast to 7.0% from 6.4% in July 2026.", "qh": "अक्टूबर 2026 के वर्ल्ड इकोनॉमिक आउटलुक में IMF ने 2026 (वित्त वर्ष 2026-27) के लिए भारत की वृद्धि दर का अनुमान कितना रखा?", "oh": ["6.4%", "5.8%", "7.0%", "8.2%"], "eh": "IMF ने भारत के 2026 के वृद्धि अनुमान को जुलाई 2026 के 6.4% से बढ़ाकर 7.0% किया।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Awards", "q": "The Fields Medal is awarded for outstanding work in:", "o": ["Mathematics", "Physics", "Medicine", "Environment"], "a": 0, "e": "The Fields Medal is given every four years by the International Mathematical Union to mathematicians under 40.", "qh": "फ़ील्ड्स मेडल किस क्षेत्र में उत्कृष्ट कार्य के लिए दिया जाता है?", "oh": ["गणित", "भौतिकी", "चिकित्सा", "पर्यावरण"], "eh": "फ़ील्ड्स मेडल अंतरराष्ट्रीय गणितीय संघ हर चार साल में 40 वर्ष से कम उम्र के गणितज्ञों को देता है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Current Affairs", "q": "INS Samarthak, commissioned at Karwar in October 2026, is the Indian Navy's first indigenous:", "o": ["Aircraft carrier", "Multi-purpose vessel", "Nuclear-powered submarine", "Stealth destroyer"], "a": 1, "e": "INS Samarthak, built by L&T with over 75% indigenous content, was commissioned on 16 October 2026 by Vice-President C. P. Radhakrishnan.", "qh": "अक्टूबर 2026 में कारवार में कमीशन हुआ INS समर्थक भारतीय नौसेना का पहला स्वदेशी क्या है?", "oh": ["विमानवाहक पोत", "बहुउद्देशीय पोत", "परमाणु-चालित पनडुब्बी", "स्टेल्थ विध्वंसक"], "eh": "L&T द्वारा बनाया गया, 75% से ज़्यादा स्वदेशी सामग्री वाला INS समर्थक 16 अक्टूबर 2026 को उपराष्ट्रपति सी. पी. राधाकृष्णन ने कमीशन किया।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Current Affairs", "q": "What was the theme of World Health Day 2026 (7 April)?", "o": ["Healthy beginnings, hopeful futures", "Together for health. Stand with science", "My health, my right", "Health for all"], "a": 1, "e": "WHO's 2026 World Health Day campaign was 'Together for health. Stand with science'. ('Healthy beginnings, hopeful futures' was 2025, 'My health, my right' 2024.)", "qh": "विश्व स्वास्थ्य दिवस 2026 (7 अप्रैल) की थीम क्या थी?", "oh": ["Healthy beginnings, hopeful futures", "Together for health. Stand with science", "My health, my right", "Health for all"], "eh": "WHO का 2026 विश्व स्वास्थ्य दिवस अभियान 'Together for health. Stand with science' था। ('Healthy beginnings, hopeful futures' 2025 और 'My health, my right' 2024 की थीम थी।)", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Geography", "q": "The Nagarjuna Sagar Dam is built on which river?", "o": ["Godavari", "Kaveri", "Krishna", "Mahanadi"], "a": 2, "e": "Nagarjuna Sagar lies on the Krishna on the Telangana–Andhra Pradesh border.", "qh": "नागार्जुन सागर बाँध किस नदी पर बना है?", "oh": ["गोदावरी", "कावेरी", "कृष्णा", "महानदी"], "eh": "नागार्जुन सागर तेलंगाना–आंध्र प्रदेश सीमा पर कृष्णा नदी पर है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "History", "q": "Who led the Revolt of 1857 at Jagdishpur in Bihar?", "o": ["Tantia Tope", "Kunwar Singh", "Nana Sahib", "Bakht Khan"], "a": 1, "e": "Kunwar Singh, the elderly zamindar of Jagdishpur, led the revolt in the Bhojpur region.", "qh": "1857 के विद्रोह में बिहार के जगदीशपुर में नेतृत्व किसने किया?", "oh": ["तात्या टोपे", "कुँवर सिंह", "नाना साहब", "बख़्त ख़ान"], "eh": "जगदीशपुर के बुज़ुर्ग ज़मींदार कुँवर सिंह ने भोजपुर क्षेत्र में विद्रोह का नेतृत्व किया।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Railways", "q": "The National Academy of Indian Railways (NAIR), which trains railway officers, is located at:", "o": ["Lucknow", "Pune", "Secunderabad", "Vadodara"], "a": 3, "e": "NAIR is housed in the Pratap Vilas Palace at Vadodara, Gujarat.", "qh": "रेलवे अधिकारियों को प्रशिक्षण देने वाली राष्ट्रीय भारतीय रेल अकादमी (NAIR) कहाँ है?", "oh": ["लखनऊ", "पुणे", "सिकंदराबाद", "वडोदरा"], "eh": "NAIR गुजरात के वडोदरा में प्रताप विलास पैलेस में है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Polity", "q": "The Goods and Services Tax (GST) was introduced through which Constitutional Amendment Act?", "o": ["73rd Amendment Act, 1992", "86th Amendment Act, 2002", "101st Amendment Act, 2016", "103rd Amendment Act, 2019"], "a": 2, "e": "The 101st Amendment (2016) added Articles 246A and 279A (GST Council); GST came into force on 1 July 2017.", "qh": "वस्तु एवं सेवा कर (GST) किस संविधान संशोधन अधिनियम से लाया गया?", "oh": ["73वाँ संशोधन अधिनियम, 1992", "86वाँ संशोधन अधिनियम, 2002", "101वाँ संशोधन अधिनियम, 2016", "103वाँ संशोधन अधिनियम, 2019"], "eh": "101वें संशोधन (2016) ने अनुच्छेद 246A और 279A (GST परिषद) जोड़े; GST 1 जुलाई 2017 से लागू हुआ।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Polity", "q": "Which Article of the Constitution directs the State to provide equal justice and free legal aid?", "o": ["Article 21A", "Article 39A", "Article 32", "Article 44"], "a": 1, "e": "Article 39A, a Directive Principle added by the 42nd Amendment (1976), deals with equal justice and free legal aid.", "qh": "संविधान का कौन-सा अनुच्छेद राज्य को समान न्याय और निःशुल्क कानूनी सहायता देने का निर्देश देता है?", "oh": ["अनुच्छेद 21A", "अनुच्छेद 39A", "अनुच्छेद 32", "अनुच्छेद 44"], "eh": "अनुच्छेद 39A, 42वें संशोधन (1976) से जोड़ा गया नीति निदेशक तत्व, समान न्याय और निःशुल्क कानूनी सहायता से जुड़ा है।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Polity", "q": "To whom does the Deputy Speaker of the Lok Sabha address the letter of resignation?", "o": ["The President", "The Prime Minister", "The Speaker", "The Vice-President"], "a": 2, "e": "Under Article 94, the Deputy Speaker resigns by writing to the Speaker, and the Speaker resigns by writing to the Deputy Speaker.", "qh": "लोकसभा का उपाध्यक्ष अपना त्यागपत्र किसे सौंपता है?", "oh": ["राष्ट्रपति को", "प्रधानमंत्री को", "अध्यक्ष (स्पीकर) को", "उपराष्ट्रपति को"], "eh": "अनुच्छेद 94 के तहत उपाध्यक्ष अध्यक्ष को और अध्यक्ष उपाध्यक्ष को लिखकर त्यागपत्र देता है।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Sports", "q": "The Davis Cup is associated with which sport?", "o": ["Golf", "Badminton", "Tennis", "Table tennis"], "a": 2, "e": "The Davis Cup is the international men's team competition in tennis.", "qh": "डेविस कप किस खेल से जुड़ा है?", "oh": ["गोल्फ़", "बैडमिंटन", "टेनिस", "टेबल टेनिस"], "eh": "डेविस कप टेनिस की अंतरराष्ट्रीय पुरुष टीम प्रतियोगिता है।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Computer", "q": "Which network device forwards data packets between different networks, such as a home network and the internet?", "o": ["Monitor", "Router", "Scanner", "Plotter"], "a": 1, "e": "A router reads the destination address of each packet and sends it on the best path between networks.", "qh": "कौन-सा नेटवर्क उपकरण अलग-अलग नेटवर्कों (जैसे घर का नेटवर्क और इंटरनेट) के बीच डेटा पैकेट आगे भेजता है?", "oh": ["मॉनिटर", "राउटर", "स्कैनर", "प्लॉटर"], "eh": "राउटर हर पैकेट का गंतव्य पता पढ़कर उसे नेटवर्कों के बीच सबसे अच्छे रास्ते से भेजता है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Static GK", "q": "World Water Day is observed every year on:", "o": ["5 June", "22 March", "22 April", "16 September"], "a": 1, "e": "World Water Day is 22 March; 5 June is World Environment Day, 22 April Earth Day and 16 September Ozone Day.", "qh": "विश्व जल दिवस हर साल कब मनाया जाता है?", "oh": ["5 जून", "22 मार्च", "22 अप्रैल", "16 सितंबर"], "eh": "विश्व जल दिवस 22 मार्च को है; 5 जून विश्व पर्यावरण दिवस, 22 अप्रैल पृथ्वी दिवस और 16 सितंबर ओज़ोन दिवस है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Sports", "q": "At the 2026 Asian Games in Aichi-Nagoya (19 Sep–4 Oct), Kumkum Mohod made history by becoming India's first woman to win individual gold in:", "o": ["Recurve archery", "Compound archery", "10 m air pistol shooting", "Javelin throw"], "a": 0, "e": "Kumkum Mohod won India's first women's individual recurve archery gold at the Asian Games. India finished the Aichi-Nagoya Games with 85 medals.", "qh": "2026 एशियाई खेलों (आइची-नागोया, 19 सितंबर–4 अक्टूबर) में कुमकुम मोहोड़ किस खेल में व्यक्तिगत स्वर्ण जीतने वाली भारत की पहली महिला बनीं?", "oh": ["रिकर्व तीरंदाज़ी", "कंपाउंड तीरंदाज़ी", "10 m एयर पिस्टल निशानेबाज़ी", "भाला फेंक"], "eh": "कुमकुम मोहोड़ ने एशियाई खेलों में भारत का पहला महिला व्यक्तिगत रिकर्व तीरंदाज़ी स्वर्ण जीता। भारत ने आइची-नागोया खेलों में 85 पदक जीते।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Polity", "q": "In the gubernatorial appointments of October 2026, who was appointed Governor of Tamil Nadu?", "o": ["Rajendra Vishwanath Arlekar", "Om Prakash Mathur", "Braj Mohan Ram", "Sudha Yadav"], "a": 0, "e": "On 12 October 2026 the President appointed Arlekar (Tamil Nadu), Om Prakash Mathur (Keralam), Braj Mohan Ram (Odisha), Sudha Yadav (Karnataka), Dhal Singh Bisen (Uttarakhand) and Dushyant Gautam (Sikkim).", "qh": "अक्टूबर 2026 की राज्यपाल नियुक्तियों में तमिलनाडु का राज्यपाल किसे बनाया गया?", "oh": ["राजेंद्र विश्वनाथ आर्लेकर", "ओम प्रकाश माथुर", "ब्रज मोहन राम", "सुधा यादव"], "eh": "12 अक्टूबर 2026 को राष्ट्रपति ने आर्लेकर (तमिलनाडु), ओम प्रकाश माथुर (केरलम), ब्रज मोहन राम (ओडिशा), सुधा यादव (कर्नाटक), ढाल सिंह बिसेन (उत्तराखंड) और दुष्यंत गौतम (सिक्किम) को नियुक्त किया।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Economy", "q": "The Pradhan Mantri Ujjwala Yojana (2016) provides:", "o": ["Free electricity connections to villages", "Houses for the urban poor", "Health insurance of ₹5 lakh per family", "LPG connections to women of poor households"], "a": 3, "e": "Ujjwala gives deposit-free LPG connections in the name of women from poor households; it was launched at Ballia, UP, on 1 May 2016.", "qh": "प्रधानमंत्री उज्ज्वला योजना (2016) क्या देती है?", "oh": ["गाँवों को मुफ़्त बिजली कनेक्शन", "शहरी गरीबों को घर", "प्रति परिवार ₹5 लाख का स्वास्थ्य बीमा", "गरीब परिवारों की महिलाओं को LPG कनेक्शन"], "eh": "उज्ज्वला गरीब परिवारों की महिलाओं के नाम पर बिना जमा राशि के LPG कनेक्शन देती है; यह 1 मई 2016 को बलिया (UP) से शुरू हुई।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Railways", "q": "In October 2026, Panna and Sidhi districts of Madhya Pradesh got regular train services for the first time. These new sections are part of which rail project?", "o": ["Indore–Dahod new line", "Ratlam–Khandwa gauge conversion", "Bhopal–Ramganj Mandi new line", "Lalitpur–Singrauli new line"], "a": 3, "e": "Satna–Devendra Nagar (53 km, Panna) and Rewa–Churhat (65 km, Sidhi) are parts of the 541 km Lalitpur–Singrauli project; services began on 24 October 2026.", "qh": "अक्टूबर 2026 में मध्य प्रदेश के पन्ना और सीधी ज़िलों को पहली बार नियमित ट्रेन सेवा मिली। ये नए खंड किस रेल परियोजना का हिस्सा हैं?", "oh": ["इंदौर–दाहोद नई लाइन", "रतलाम–खंडवा गेज परिवर्तन", "भोपाल–रामगंज मंडी नई लाइन", "ललितपुर–सिंगरौली नई लाइन"], "eh": "सतना–देवेंद्र नगर (53 km, पन्ना) और रीवा–चुरहट (65 km, सीधी) 541 km लंबी ललितपुर–सिंगरौली परियोजना के हिस्से हैं; सेवाएँ 24 अक्टूबर 2026 को शुरू हुईं।", "level": "tough"}]});
